  "version": "2.2.0",
  "license": "BSD-2-Clause",
  "author": "Felix Gnass <fgnass@gmail.com>",
  "description": "Server-side DOM implementation based on Mozilla's dom.js",
  "main": "./lib",
  "repository": {
    "type": "git",
    "url": "https://github.com/mixmark-io/domino.git"
  },
  "scripts": {
    "test": "mocha"
  },
  "types": "lib/index.d.ts",
  "devDependencies": {
    "jquery": "^3.5.1",
    "mocha": "^6.2.3",
    "puppeteer": "^21.3.5",
    "should": "^13.2.3"
  }
}

{
  "name": "@tiptap/core",
  "version": "3.31.0",
  "description": "headless rich text editor",
  "keywords": [
    "headless",
    "prosemirror",
    "text editor",
    "tiptap",
    "wysiwyg"
  ],
  "homepage": "https://tiptap.dev",
  "bugs": {
    "url": "https://github.com/ueberdosis/tiptap/issues"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/ueberdosis/tiptap",
    "directory": "packages/core"
  },
  "funding": {
    "type": "github",
    "url": "https://github.com/sponsors/ueberdosis"
  },
  "files": [
    "src",
    "dist",
    "jsx-runtime",
    "jsx-dev-runtime"
  ],
  "type": "module",
  "sideEffects": false,
  "main": "dist/index.cjs",
  "module": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": {
        "import": "./dist/index.d.ts",
        "require": "./dist/index.d.cts"
      },
      "import": "./dist/index.js",
      "require": "./dist/index.cjs"
    },
    "./jsx-runtime": {
      "types": {
        "import": "./jsx-runtime/index.d.ts",
        "require": "./jsx-runtime/index.d.cts"
      },
      "import": "./jsx-runtime/index.js",
      "require": "./jsx-runtime/index.cjs"
    },
    "./jsx-dev-runtime": {
      "types": {
        "import": "./jsx-dev-runtime/index.d.ts",
        "require": "./jsx-dev-runtime/index.d.cts"
      },
      "import": "./jsx-dev-runtime/index.js",
      "require": "./jsx-dev-runtime/index.cjs"
    }
  },
  "devDependencies": {
    "prosemirror-model": "^1.25.11",
    "@tiptap/pm": "^3.31.0"
  },
  "peerDependencies": {
    "@tiptap/pm": "3.31.0"
  },
  "scripts": {
    "build": "vp pack"
  }
}

