      "default": "./lite/tiktoken_bg.wasm"
    },
    "./lite/tiktoken_bg.wasm?module": {
      "types": "./lite/tiktoken_bg.wasm.d.ts",
      "default": "./lite/tiktoken_bg.wasm?module"
